ALTER TABLE "pre_market_ideas" ADD COLUMN "book" varchar(8);--> statement-breakpoint
ALTER TABLE "trading_risk_settings" ADD COLUMN "swing_allocation_percent" numeric;--> statement-breakpoint
ALTER TABLE "trading_risk_settings" ADD COLUMN "day_risk_per_trade_percent" numeric;--> statement-breakpoint
ALTER TABLE "pre_market_ideas" ADD CONSTRAINT "pre_market_ideas_book_check" CHECK ("pre_market_ideas"."book" is null or "pre_market_ideas"."book" in ('day', 'swing'));--> statement-breakpoint
ALTER TABLE "trading_risk_settings" ADD CONSTRAINT "trading_risk_settings_books_check" CHECK (("trading_risk_settings"."swing_allocation_percent" is null) = ("trading_risk_settings"."day_risk_per_trade_percent" is null) and ("trading_risk_settings"."swing_allocation_percent" is null or ("trading_risk_settings"."swing_allocation_percent" >= 0 and "trading_risk_settings"."swing_allocation_percent" <= 100 and "trading_risk_settings"."day_risk_per_trade_percent" > 0 and "trading_risk_settings"."day_risk_per_trade_percent" <= 100 and ("trading_risk_settings"."daily_loss_percent" is null or "trading_risk_settings"."day_risk_per_trade_percent" <= "trading_risk_settings"."daily_loss_percent"))));